exec:
const ts = String(Math.floor(Date.now() / 1000));
const id = pm.variables.replaceIn('{{mpPagoId}}').toLowerCase();
const manifest = `id:${id};request-id:${pm.variables.replaceIn('postman-{{run}}')};ts:${ts};`;
const v1 = CryptoJS.HmacSHA256(manifest, pm.variables.get('mpSecret')).toString(CryptoJS.enc.Hex);
pm.collectionVariables.set('firmaMp', `ts=${ts},v1=${v1}`);

